-- =====================================================================
-- 01_data_quality_checks.sql
-- Project : Social Media Usage, Dopamine & Productivity Analysis (MySQL)
-- Purpose : Check the raw table for nulls, duplicates, extra spaces,
--           inconsistent text case, out-of-range values and distinct values.
-- Before running: import the raw CSV into the table `social_media_dopamine_productivity`
--           (for example with MySQL Workbench Table Data Import Wizard).
-- NOTE: this script only CHECKS the data. It does not change it.
-- =====================================================================

CREATE DATABASE IF NOT EXISTS social_media_analytics;
USE social_media_analytics;

-- ---------- 1. Basic look ----------
SHOW TABLES;

SELECT COUNT(*) AS total_rows
FROM social_media_dopamine_productivity;

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_name = 'social_media_dopamine_productivity'
  AND table_schema = DATABASE();

-- ---------- 2. Duplicates ----------
-- Any participant_id that appears more than once
SELECT participant_id, COUNT(*) AS occurrence_count
FROM social_media_dopamine_productivity
GROUP BY participant_id
HAVING COUNT(*) > 1;

-- Total rows vs unique rows (the two numbers should match)
SELECT COUNT(*) AS total_rows
FROM social_media_dopamine_productivity;

SELECT COUNT(*) AS unique_rows
FROM (SELECT DISTINCT * FROM social_media_dopamine_productivity) t;

-- ---------- 3. Null check on every column ----------
-- Step 1: this query WRITES the null-check query for all columns
-- (so I do not type 60 columns by hand). Copy its output, then run it.
SET SESSION group_concat_max_len = 100000;

SELECT GROUP_CONCAT(
    CONCAT('SUM(CASE WHEN ', column_name, ' IS NULL THEN 1 ELSE 0 END) AS ', column_name, '_nulls')
    SEPARATOR ', '
) AS null_check_query
FROM information_schema.columns
WHERE table_name = 'social_media_dopamine_productivity'
  AND table_schema = DATABASE();

-- Step 2: the generated query, run on the table
SELECT SUM(CASE WHEN participant_id IS NULL THEN 1 ELSE 0 END) AS participant_id_nulls, SUM(CASE WHEN data_source IS NULL THEN 1 ELSE 0 END) AS data_source_nulls, SUM(CASE WHEN synthetic_flag IS NULL THEN 1 ELSE 0 END) AS synthetic_flag_nulls, SUM(CASE WHEN age IS NULL THEN 1 ELSE 0 END) AS age_nulls, SUM(CASE WHEN age_group IS NULL THEN 1 ELSE 0 END) AS age_group_nulls, SUM(CASE WHEN gender IS NULL THEN 1 ELSE 0 END) AS gender_nulls, SUM(CASE WHEN race_ethnicity IS NULL THEN 1 ELSE 0 END) AS race_ethnicity_nulls, SUM(CASE WHEN nationality IS NULL THEN 1 ELSE 0 END) AS nationality_nulls, SUM(CASE WHEN country_of_residence IS NULL THEN 1 ELSE 0 END) AS country_of_residence_nulls, SUM(CASE WHEN education_level IS NULL THEN 1 ELSE 0 END) AS education_level_nulls, SUM(CASE WHEN employment_status IS NULL THEN 1 ELSE 0 END) AS employment_status_nulls, SUM(CASE WHEN occupation_category IS NULL THEN 1 ELSE 0 END) AS occupation_category_nulls, SUM(CASE WHEN relationship_status IS NULL THEN 1 ELSE 0 END) AS relationship_status_nulls, SUM(CASE WHEN avg_daily_sm_hours IS NULL THEN 1 ELSE 0 END) AS avg_daily_sm_hours_nulls, SUM(CASE WHEN years_on_social_media IS NULL THEN 1 ELSE 0 END) AS years_on_social_media_nulls, SUM(CASE WHEN primary_platform IS NULL THEN 1 ELSE 0 END) AS primary_platform_nulls, SUM(CASE WHEN secondary_platform IS NULL THEN 1 ELSE 0 END) AS secondary_platform_nulls, SUM(CASE WHEN daily_check_frequency IS NULL THEN 1 ELSE 0 END) AS daily_check_frequency_nulls, SUM(CASE WHEN first_check_of_day IS NULL THEN 1 ELSE 0 END) AS first_check_of_day_nulls, SUM(CASE WHEN late_night_scrolling IS NULL THEN 1 ELSE 0 END) AS late_night_scrolling_nulls, SUM(CASE WHEN sm_during_work_study IS NULL THEN 1 ELSE 0 END) AS sm_during_work_study_nulls, SUM(CASE WHEN sm_during_meals IS NULL THEN 1 ELSE 0 END) AS sm_during_meals_nulls, SUM(CASE WHEN notifications_always_on IS NULL THEN 1 ELSE 0 END) AS notifications_always_on_nulls, SUM(CASE WHEN scroll_without_purpose IS NULL THEN 1 ELSE 0 END) AS scroll_without_purpose_nulls, SUM(CASE WHEN doomscrolling_frequency IS NULL THEN 1 ELSE 0 END) AS doomscrolling_frequency_nulls, SUM(CASE WHEN content_type_consumed IS NULL THEN 1 ELSE 0 END) AS content_type_consumed_nulls, SUM(CASE WHEN avg_daily_screen_time_hours IS NULL THEN 1 ELSE 0 END) AS avg_daily_screen_time_hours_nulls, SUM(CASE WHEN avg_sleep_hours IS NULL THEN 1 ELSE 0 END) AS avg_sleep_hours_nulls, SUM(CASE WHEN sleep_quality IS NULL THEN 1 ELSE 0 END) AS sleep_quality_nulls, SUM(CASE WHEN exercise_frequency IS NULL THEN 1 ELSE 0 END) AS exercise_frequency_nulls, SUM(CASE WHEN avg_work_study_hours_per_day IS NULL THEN 1 ELSE 0 END) AS avg_work_study_hours_per_day_nulls, SUM(CASE WHEN dopamine_rush_feel_score IS NULL THEN 1 ELSE 0 END) AS dopamine_rush_feel_score_nulls, SUM(CASE WHEN reward_seeking_behavior IS NULL THEN 1 ELSE 0 END) AS reward_seeking_behavior_nulls, SUM(CASE WHEN fomo_score IS NULL THEN 1 ELSE 0 END) AS fomo_score_nulls, SUM(CASE WHEN comparison_to_others_score IS NULL THEN 1 ELSE 0 END) AS comparison_to_others_score_nulls, SUM(CASE WHEN validation_seeking_score IS NULL THEN 1 ELSE 0 END) AS validation_seeking_score_nulls, SUM(CASE WHEN boredom_to_phone_reflex IS NULL THEN 1 ELSE 0 END) AS boredom_to_phone_reflex_nulls, SUM(CASE WHEN inability_to_delay_gratification IS NULL THEN 1 ELSE 0 END) AS inability_to_delay_gratification_nulls, SUM(CASE WHEN attention_span_minutes IS NULL THEN 1 ELSE 0 END) AS attention_span_minutes_nulls, SUM(CASE WHEN deep_work_duration_minutes IS NULL THEN 1 ELSE 0 END) AS deep_work_duration_minutes_nulls, SUM(CASE WHEN task_switching_frequency IS NULL THEN 1 ELSE 0 END) AS task_switching_frequency_nulls, SUM(CASE WHEN difficulty_starting_tasks IS NULL THEN 1 ELSE 0 END) AS difficulty_starting_tasks_nulls, SUM(CASE WHEN difficulty_maintaining_focus IS NULL THEN 1 ELSE 0 END) AS difficulty_maintaining_focus_nulls, SUM(CASE WHEN mind_wandering_during_work IS NULL THEN 1 ELSE 0 END) AS mind_wandering_during_work_nulls, SUM(CASE WHEN productivity_self_rating IS NULL THEN 1 ELSE 0 END) AS productivity_self_rating_nulls, SUM(CASE WHEN tasks_completed_per_day IS NULL THEN 1 ELSE 0 END) AS tasks_completed_per_day_nulls, SUM(CASE WHEN work_quality_self_rating IS NULL THEN 1 ELSE 0 END) AS work_quality_self_rating_nulls, SUM(CASE WHEN creative_output_frequency IS NULL THEN 1 ELSE 0 END) AS creative_output_frequency_nulls, SUM(CASE WHEN reading_duration_minutes_per_day IS NULL THEN 1 ELSE 0 END) AS reading_duration_minutes_per_day_nulls, SUM(CASE WHEN memory_recall_difficulty IS NULL THEN 1 ELSE 0 END) AS memory_recall_difficulty_nulls, SUM(CASE WHEN learning_retention_difficulty IS NULL THEN 1 ELSE 0 END) AS learning_retention_difficulty_nulls, SUM(CASE WHEN decision_fatigue_score IS NULL THEN 1 ELSE 0 END) AS decision_fatigue_score_nulls, SUM(CASE WHEN mental_fog_frequency IS NULL THEN 1 ELSE 0 END) AS mental_fog_frequency_nulls, SUM(CASE WHEN irritability_when_offline IS NULL THEN 1 ELSE 0 END) AS irritability_when_offline_nulls, SUM(CASE WHEN anxiety_when_phone_unavailable IS NULL THEN 1 ELSE 0 END) AS anxiety_when_phone_unavailable_nulls, SUM(CASE WHEN restlessness_score IS NULL THEN 1 ELSE 0 END) AS restlessness_score_nulls, SUM(CASE WHEN mood_dependency_on_sm IS NULL THEN 1 ELSE 0 END) AS mood_dependency_on_sm_nulls, SUM(CASE WHEN withdrawal_attempt_count IS NULL THEN 1 ELSE 0 END) AS withdrawal_attempt_count_nulls, SUM(CASE WHEN longest_detox_days IS NULL THEN 1 ELSE 0 END) AS longest_detox_days_nulls, SUM(CASE WHEN detox_relapse_reason IS NULL THEN 1 ELSE 0 END) AS detox_relapse_reason_nulls, SUM(CASE WHEN severity_stage IS NULL THEN 1 ELSE 0 END) AS severity_stage_nulls, SUM(CASE WHEN productivity_decline_score IS NULL THEN 1 ELSE 0 END) AS productivity_decline_score_nulls, SUM(CASE WHEN dopamine_dysregulation_index IS NULL THEN 1 ELSE 0 END) AS dopamine_dysregulation_index_nulls, SUM(CASE WHEN digital_wellbeing_score IS NULL THEN 1 ELSE 0 END) AS digital_wellbeing_score_nulls, SUM(CASE WHEN sm_addiction_risk_score IS NULL THEN 1 ELSE 0 END) AS sm_addiction_risk_score_nulls, SUM(CASE WHEN notes IS NULL THEN 1 ELSE 0 END) AS notes_nulls
FROM social_media_dopamine_productivity;

-- ---------- 4. Extra spaces in text columns ----------
-- Step 1: generator
SELECT GROUP_CONCAT(
    CONCAT('SUM(CASE WHEN ', column_name, ' <> TRIM(', column_name, ') THEN 1 ELSE 0 END) AS ', column_name, '_untrimmed')
    SEPARATOR ', '
) AS check_query
FROM information_schema.columns
WHERE table_name = 'social_media_dopamine_productivity'
  AND table_schema = DATABASE()
  AND data_type IN ('varchar','text','char');

-- Step 2: the generated query
SELECT 
SUM(CASE WHEN participant_id <> TRIM(participant_id) THEN 1 ELSE 0 END) AS participant_id_untrimmed, SUM(CASE WHEN data_source <> TRIM(data_source) THEN 1 ELSE 0 END) AS data_source_untrimmed, SUM(CASE WHEN age_group <> TRIM(age_group) THEN 1 ELSE 0 END) AS age_group_untrimmed, SUM(CASE WHEN gender <> TRIM(gender) THEN 1 ELSE 0 END) AS gender_untrimmed, SUM(CASE WHEN race_ethnicity <> TRIM(race_ethnicity) THEN 1 ELSE 0 END) AS race_ethnicity_untrimmed, SUM(CASE WHEN nationality <> TRIM(nationality) THEN 1 ELSE 0 END) AS nationality_untrimmed, SUM(CASE WHEN country_of_residence <> TRIM(country_of_residence) THEN 1 ELSE 0 END) AS country_of_residence_untrimmed, SUM(CASE WHEN education_level <> TRIM(education_level) THEN 1 ELSE 0 END) AS education_level_untrimmed, SUM(CASE WHEN employment_status <> TRIM(employment_status) THEN 1 ELSE 0 END) AS employment_status_untrimmed, SUM(CASE WHEN occupation_category <> TRIM(occupation_category) THEN 1 ELSE 0 END) AS occupation_category_untrimmed, SUM(CASE WHEN relationship_status <> TRIM(relationship_status) THEN 1 ELSE 0 END) AS relationship_status_untrimmed, SUM(CASE WHEN primary_platform <> TRIM(primary_platform) THEN 1 ELSE 0 END) AS primary_platform_untrimmed, SUM(CASE WHEN secondary_platform <> TRIM(secondary_platform) THEN 1 ELSE 0 END) AS secondary_platform_untrimmed, SUM(CASE WHEN daily_check_frequency <> TRIM(daily_check_frequency) THEN 1 ELSE 0 END) AS daily_check_frequency_untrimmed, SUM(CASE WHEN first_check_of_day <> TRIM(first_check_of_day) THEN 1 ELSE 0 END) AS first_check_of_day_untrimmed, SUM(CASE WHEN late_night_scrolling <> TRIM(late_night_scrolling) THEN 1 ELSE 0 END) AS late_night_scrolling_untrimmed, SUM(CASE WHEN sm_during_work_study <> TRIM(sm_during_work_study) THEN 1 ELSE 0 END) AS sm_during_work_study_untrimmed, SUM(CASE WHEN sm_during_meals <> TRIM(sm_during_meals) THEN 1 ELSE 0 END) AS sm_during_meals_untrimmed, SUM(CASE WHEN notifications_always_on <> TRIM(notifications_always_on) THEN 1 ELSE 0 END) AS notifications_always_on_untrimmed, SUM(CASE WHEN scroll_without_purpose <> TRIM(scroll_without_purpose) THEN 1 ELSE 0 END) AS scroll_without_purpose_untrimmed, SUM(CASE WHEN doomscrolling_frequency <> TRIM(doomscrolling_frequency) THEN 1 ELSE 0 END) AS doomscrolling_frequency_untrimmed, SUM(CASE WHEN content_type_consumed <> TRIM(content_type_consumed) THEN 1 ELSE 0 END) AS content_type_consumed_untrimmed, SUM(CASE WHEN sleep_quality <> TRIM(sleep_quality) THEN 1 ELSE 0 END) AS sleep_quality_untrimmed, SUM(CASE WHEN exercise_frequency <> TRIM(exercise_frequency) THEN 1 ELSE 0 END) AS exercise_frequency_untrimmed, SUM(CASE WHEN boredom_to_phone_reflex <> TRIM(boredom_to_phone_reflex) THEN 1 ELSE 0 END) AS boredom_to_phone_reflex_untrimmed, SUM(CASE WHEN inability_to_delay_gratification <> TRIM(inability_to_delay_gratification) THEN 1 ELSE 0 END) AS inability_to_delay_gratification_untrimmed, SUM(CASE WHEN task_switching_frequency <> TRIM(task_switching_frequency) THEN 1 ELSE 0 END) AS task_switching_frequency_untrimmed, SUM(CASE WHEN difficulty_starting_tasks <> TRIM(difficulty_starting_tasks) THEN 1 ELSE 0 END) AS difficulty_starting_tasks_untrimmed, SUM(CASE WHEN difficulty_maintaining_focus <> TRIM(difficulty_maintaining_focus) THEN 1 ELSE 0 END) AS difficulty_maintaining_focus_untrimmed, SUM(CASE WHEN mind_wandering_during_work <> TRIM(mind_wandering_during_work) THEN 1 ELSE 0 END) AS mind_wandering_during_work_untrimmed, SUM(CASE WHEN creative_output_frequency <> TRIM(creative_output_frequency) THEN 1 ELSE 0 END) AS creative_output_frequency_untrimmed, SUM(CASE WHEN memory_recall_difficulty <> TRIM(memory_recall_difficulty) THEN 1 ELSE 0 END) AS memory_recall_difficulty_untrimmed, SUM(CASE WHEN learning_retention_difficulty <> TRIM(learning_retention_difficulty) THEN 1 ELSE 0 END) AS learning_retention_difficulty_untrimmed, SUM(CASE WHEN mental_fog_frequency <> TRIM(mental_fog_frequency) THEN 1 ELSE 0 END) AS mental_fog_frequency_untrimmed, SUM(CASE WHEN irritability_when_offline <> TRIM(irritability_when_offline) THEN 1 ELSE 0 END) AS irritability_when_offline_untrimmed, SUM(CASE WHEN mood_dependency_on_sm <> TRIM(mood_dependency_on_sm) THEN 1 ELSE 0 END) AS mood_dependency_on_sm_untrimmed, SUM(CASE WHEN severity_stage <> TRIM(severity_stage) THEN 1 ELSE 0 END) AS severity_stage_untrimmed, SUM(CASE WHEN productivity_decline_score <> TRIM(productivity_decline_score) THEN 1 ELSE 0 END) AS productivity_decline_score_untrimmed


FROM social_media_dopamine_productivity;

-- ---------- 5. Inconsistent text case (e.g. 'Male' vs 'male') ----------
-- BINARY makes the distinct count case-sensitive. MySQL text comparison is
-- normally case-insensitive, so without BINARY this check would always return 0.
-- Result 1 = that column has a case problem, 0 = fine.
SELECT GROUP_CONCAT(
    CONCAT('CASE WHEN COUNT(DISTINCT BINARY ', column_name, ') <> COUNT(DISTINCT UPPER(', column_name, ')) THEN 1 ELSE 0 END AS ', column_name, '_case_issue')
    SEPARATOR ', '
) AS check_query
FROM information_schema.columns
WHERE table_name = 'social_media_dopamine_productivity'
  AND table_schema = DATABASE()
  AND data_type IN ('varchar','text','char');

SELECT 
CASE WHEN COUNT(DISTINCT BINARY participant_id) <> COUNT(DISTINCT UPPER(participant_id)) THEN 1 ELSE 0 END AS participant_id_case_issue, CASE WHEN COUNT(DISTINCT BINARY data_source) <> COUNT(DISTINCT UPPER(data_source)) THEN 1 ELSE 0 END AS data_source_case_issue, CASE WHEN COUNT(DISTINCT BINARY age_group) <> COUNT(DISTINCT UPPER(age_group)) THEN 1 ELSE 0 END AS age_group_case_issue, CASE WHEN COUNT(DISTINCT BINARY gender) <> COUNT(DISTINCT UPPER(gender)) THEN 1 ELSE 0 END AS gender_case_issue, CASE WHEN COUNT(DISTINCT BINARY race_ethnicity) <> COUNT(DISTINCT UPPER(race_ethnicity)) THEN 1 ELSE 0 END AS race_ethnicity_case_issue, CASE WHEN COUNT(DISTINCT BINARY nationality) <> COUNT(DISTINCT UPPER(nationality)) THEN 1 ELSE 0 END AS nationality_case_issue, CASE WHEN COUNT(DISTINCT BINARY country_of_residence) <> COUNT(DISTINCT UPPER(country_of_residence)) THEN 1 ELSE 0 END AS country_of_residence_case_issue, CASE WHEN COUNT(DISTINCT BINARY education_level) <> COUNT(DISTINCT UPPER(education_level)) THEN 1 ELSE 0 END AS education_level_case_issue, CASE WHEN COUNT(DISTINCT BINARY employment_status) <> COUNT(DISTINCT UPPER(employment_status)) THEN 1 ELSE 0 END AS employment_status_case_issue, CASE WHEN COUNT(DISTINCT BINARY occupation_category) <> COUNT(DISTINCT UPPER(occupation_category)) THEN 1 ELSE 0 END AS occupation_category_case_issue, CASE WHEN COUNT(DISTINCT BINARY relationship_status) <> COUNT(DISTINCT UPPER(relationship_status)) THEN 1 ELSE 0 END AS relationship_status_case_issue, CASE WHEN COUNT(DISTINCT BINARY primary_platform) <> COUNT(DISTINCT UPPER(primary_platform)) THEN 1 ELSE 0 END AS primary_platform_case_issue, CASE WHEN COUNT(DISTINCT BINARY secondary_platform) <> COUNT(DISTINCT UPPER(secondary_platform)) THEN 1 ELSE 0 END AS secondary_platform_case_issue, CASE WHEN COUNT(DISTINCT BINARY daily_check_frequency) <> COUNT(DISTINCT UPPER(daily_check_frequency)) THEN 1 ELSE 0 END AS daily_check_frequency_case_issue, CASE WHEN COUNT(DISTINCT BINARY first_check_of_day) <> COUNT(DISTINCT UPPER(first_check_of_day)) THEN 1 ELSE 0 END AS first_check_of_day_case_issue, CASE WHEN COUNT(DISTINCT BINARY late_night_scrolling) <> COUNT(DISTINCT UPPER(late_night_scrolling)) THEN 1 ELSE 0 END AS late_night_scrolling_case_issue, CASE WHEN COUNT(DISTINCT BINARY sm_during_work_study) <> COUNT(DISTINCT UPPER(sm_during_work_study)) THEN 1 ELSE 0 END AS sm_during_work_study_case_issue, CASE WHEN COUNT(DISTINCT BINARY sm_during_meals) <> COUNT(DISTINCT UPPER(sm_during_meals)) THEN 1 ELSE 0 END AS sm_during_meals_case_issue, CASE WHEN COUNT(DISTINCT BINARY notifications_always_on) <> COUNT(DISTINCT UPPER(notifications_always_on)) THEN 1 ELSE 0 END AS notifications_always_on_case_issue, CASE WHEN COUNT(DISTINCT BINARY scroll_without_purpose) <> COUNT(DISTINCT UPPER(scroll_without_purpose)) THEN 1 ELSE 0 END AS scroll_without_purpose_case_issue, CASE WHEN COUNT(DISTINCT BINARY doomscrolling_frequency) <> COUNT(DISTINCT UPPER(doomscrolling_frequency)) THEN 1 ELSE 0 END AS doomscrolling_frequency_case_issue, CASE WHEN COUNT(DISTINCT BINARY content_type_consumed) <> COUNT(DISTINCT UPPER(content_type_consumed)) THEN 1 ELSE 0 END AS content_type_consumed_case_issue, CASE WHEN COUNT(DISTINCT BINARY sleep_quality) <> COUNT(DISTINCT UPPER(sleep_quality)) THEN 1 ELSE 0 END AS sleep_quality_case_issue, CASE WHEN COUNT(DISTINCT BINARY exercise_frequency) <> COUNT(DISTINCT UPPER(exercise_frequency)) THEN 1 ELSE 0 END AS exercise_frequency_case_issue, CASE WHEN COUNT(DISTINCT BINARY boredom_to_phone_reflex) <> COUNT(DISTINCT UPPER(boredom_to_phone_reflex)) THEN 1 ELSE 0 END AS boredom_to_phone_reflex_case_issue, CASE WHEN COUNT(DISTINCT BINARY inability_to_delay_gratification) <> COUNT(DISTINCT UPPER(inability_to_delay_gratification)) THEN 1 ELSE 0 END AS inability_to_delay_gratification_case_issue, CASE WHEN COUNT(DISTINCT BINARY task_switching_frequency) <> COUNT(DISTINCT UPPER(task_switching_frequency)) THEN 1 ELSE 0 END AS task_switching_frequency_case_issue, CASE WHEN COUNT(DISTINCT BINARY difficulty_starting_tasks) <> COUNT(DISTINCT UPPER(difficulty_starting_tasks)) THEN 1 ELSE 0 END AS difficulty_starting_tasks_case_issue, CASE WHEN COUNT(DISTINCT BINARY difficulty_maintaining_focus) <> COUNT(DISTINCT UPPER(difficulty_maintaining_focus)) THEN 1 ELSE 0 END AS difficulty_maintaining_focus_case_issue, CASE WHEN COUNT(DISTINCT BINARY mind_wandering_during_work) <> COUNT(DISTINCT UPPER(mind_wandering_during_work)) THEN 1 ELSE 0 END AS mind_wandering_during_work_case_issue, CASE WHEN COUNT(DISTINCT BINARY creative_output_frequency) <> COUNT(DISTINCT UPPER(creative_output_frequency)) THEN 1 ELSE 0 END AS creative_output_frequency_case_issue, CASE WHEN COUNT(DISTINCT BINARY memory_recall_difficulty) <> COUNT(DISTINCT UPPER(memory_recall_difficulty)) THEN 1 ELSE 0 END AS memory_recall_difficulty_case_issue, CASE WHEN COUNT(DISTINCT BINARY learning_retention_difficulty) <> COUNT(DISTINCT UPPER(learning_retention_difficulty)) THEN 1 ELSE 0 END AS learning_retention_difficulty_case_issue, CASE WHEN COUNT(DISTINCT BINARY mental_fog_frequency) <> COUNT(DISTINCT UPPER(mental_fog_frequency)) THEN 1 ELSE 0 END AS mental_fog_frequency_case_issue, CASE WHEN COUNT(DISTINCT BINARY irritability_when_offline) <> COUNT(DISTINCT UPPER(irritability_when_offline)) THEN 1 ELSE 0 END AS irritability_when_offline_case_issue, CASE WHEN COUNT(DISTINCT BINARY mood_dependency_on_sm) <> COUNT(DISTINCT UPPER(mood_dependency_on_sm)) THEN 1 ELSE 0 END AS mood_dependency_on_sm_case_issue, CASE WHEN COUNT(DISTINCT BINARY severity_stage) <> COUNT(DISTINCT UPPER(severity_stage)) THEN 1 ELSE 0 END AS severity_stage_case_issue, CASE WHEN COUNT(DISTINCT BINARY productivity_decline_score) <> COUNT(DISTINCT UPPER(productivity_decline_score)) THEN 1 ELSE 0 END AS productivity_decline_score_case_issue

  
FROM social_media_dopamine_productivity;

-- ---------- 6. Value ranges of numeric columns (min and max) ----------
SELECT GROUP_CONCAT(
    CONCAT('MIN(', column_name, ') AS ', column_name, '_min, MAX(', column_name, ') AS ', column_name, '_max')
    SEPARATOR ', '
) AS check_query
FROM information_schema.columns
WHERE table_name = 'social_media_dopamine_productivity'
  AND table_schema = DATABASE()
  AND data_type IN ('int','decimal','double','float','bigint','tinyint','smallint');

SELECT 
   MIN(synthetic_flag) AS synthetic_flag_min, MAX(synthetic_flag) AS synthetic_flag_max, MIN(age) AS age_min, MAX(age) AS age_max, MIN(avg_daily_sm_hours) AS avg_daily_sm_hours_min, MAX(avg_daily_sm_hours) AS avg_daily_sm_hours_max, MIN(years_on_social_media) AS years_on_social_media_min, MAX(years_on_social_media) AS years_on_social_media_max, MIN(avg_daily_screen_time_hours) AS avg_daily_screen_time_hours_min, MAX(avg_daily_screen_time_hours) AS avg_daily_screen_time_hours_max, MIN(avg_sleep_hours) AS avg_sleep_hours_min, MAX(avg_sleep_hours) AS avg_sleep_hours_max, MIN(avg_work_study_hours_per_day) AS avg_work_study_hours_per_day_min, MAX(avg_work_study_hours_per_day) AS avg_work_study_hours_per_day_max, MIN(dopamine_rush_feel_score) AS dopamine_rush_feel_score_min, MAX(dopamine_rush_feel_score) AS dopamine_rush_feel_score_max, MIN(reward_seeking_behavior) AS reward_seeking_behavior_min, MAX(reward_seeking_behavior) AS reward_seeking_behavior_max, MIN(fomo_score) AS fomo_score_min, MAX(fomo_score) AS fomo_score_max, MIN(comparison_to_others_score) AS comparison_to_others_score_min, MAX(comparison_to_others_score) AS comparison_to_others_score_max, MIN(validation_seeking_score) AS validation_seeking_score_min, MAX(validation_seeking_score) AS validation_seeking_score_max, MIN(attention_span_minutes) AS attention_span_minutes_min, MAX(attention_span_minutes) AS attention_span_minutes_max, MIN(deep_work_duration_minutes) AS deep_work_duration_minutes_min, MAX(deep_work_duration_minutes) AS deep_work_duration_minutes_max, MIN(productivity_self_rating) AS productivity_self_rating_min, MAX(productivity_self_rating) AS productivity_self_rating_max, MIN(tasks_completed_per_day) AS tasks_completed_per_day_min, MAX(tasks_completed_per_day) AS tasks_completed_per_day_max, MIN(work_quality_self_rating) AS work_quality_self_rating_min, MAX(work_quality_self_rating) AS work_quality_self_rating_max, MIN(reading_duration_minutes_per_day) AS reading_duration_minutes_per_day_min, MAX(reading_duration_minutes_per_day) AS reading_duration_minutes_per_day_max, MIN(decision_fatigue_score) AS decision_fatigue_score_min, MAX(decision_fatigue_score) AS decision_fatigue_score_max, MIN(anxiety_when_phone_unavailable) AS anxiety_when_phone_unavailable_min, MAX(anxiety_when_phone_unavailable) AS anxiety_when_phone_unavailable_max, MIN(restlessness_score) AS restlessness_score_min, MAX(restlessness_score) AS restlessness_score_max, MIN(withdrawal_attempt_count) AS withdrawal_attempt_count_min, MAX(withdrawal_attempt_count) AS withdrawal_attempt_count_max, MIN(longest_detox_days) AS longest_detox_days_min, MAX(longest_detox_days) AS longest_detox_days_max, MIN(detox_relapse_reason) AS detox_relapse_reason_min, MAX(detox_relapse_reason) AS detox_relapse_reason_max, MIN(dopamine_dysregulation_index) AS dopamine_dysregulation_index_min, MAX(dopamine_dysregulation_index) AS dopamine_dysregulation_index_max, MIN(digital_wellbeing_score) AS digital_wellbeing_score_min, MAX(digital_wellbeing_score) AS digital_wellbeing_score_max, MIN(sm_addiction_risk_score) AS sm_addiction_risk_score_min, MAX(sm_addiction_risk_score) AS sm_addiction_risk_score_max, MIN(notes) AS notes_min, MAX(notes) AS notes_max

FROM social_media_dopamine_productivity;

-- ---------- 7. Number of distinct values in text columns ----------
SELECT GROUP_CONCAT(
    CONCAT('COUNT(DISTINCT ', column_name, ') AS ', column_name, '_distinct_count')
    SEPARATOR ', '
) AS check_query
FROM information_schema.columns
WHERE table_name = 'social_media_dopamine_productivity'
  AND table_schema = DATABASE()
  AND data_type IN ('varchar','text','char');

